const plannerThemes={
beach:[1,3,8,11,14,18],surf:[35,36,37,38,39,40],mountain:[2,4,7,10,17],food:[15,24,25],culture:[5,6,9,12,13,16,20,21,22],adventure:[2,4,7,8,17,18],nightlife:[23,24,25,26,27],horse:[16,17],fourbyfour:[7,8,10],mix:[1,2,3,5,6,7,8,10,11,12,13,14,15,16,17,18,20,21,23,24,25,27,35,36,39]};
const plannerRegion={west:[1,2,12,13,14,16,17,20,21],central:[3,4,5,6,15,19,23,24,25,26,27,34,35,36,37,38],east:[7,8,9,10,11,18,22,39,40]};
let plannerDays=3;
function placeRegion(id){return Object.keys(plannerRegion).find(region=>plannerRegion[region].includes(id))||"central"}
function regionLabel(region){const labels={en:{west:"Western El Salvador",central:"Central El Salvador",east:"Eastern El Salvador"},es:{west:"Occidente de El Salvador",central:"Centro de El Salvador",east:"Oriente de El Salvador"},fr:{west:"Ouest du Salvador",central:"Centre du Salvador",east:"Est du Salvador"}};return labels[lang][region]}
function buildItinerary(){
 const selectedThemes=[...document.querySelectorAll(".interest:checked")].map(x=>x.value);
 const themes=selectedThemes.length?selectedThemes:["mix"],pace=document.getElementById("tripPace").value,start=document.getElementById("tripStart").value;
 const perDay={relaxed:2,balanced:3,active:4}[pace],scores=new Map();
 themes.forEach((theme,themeIndex)=>(plannerThemes[theme]||[]).forEach((id,index)=>scores.set(id,(scores.get(id)||0)+100-index-themeIndex)));
 if(!themes.includes("mix"))plannerThemes.mix.forEach((id,index)=>{if(!scores.has(id))scores.set(id,10-index/10)});
 let candidates=places.filter(p=>p.id!==19&&scores.has(p.id));
 const regionOrder=start==="west"?["west","central","east"]:start==="east"?["east","central","west"]:["central","west","east"];
 candidates.sort((a,b)=>regionOrder.indexOf(placeRegion(a.id))-regionOrder.indexOf(placeRegion(b.id))||(scores.get(b.id)-scores.get(a.id)));
 const needed=Math.min(candidates.length,plannerDays*perDay),chosen=candidates.slice(0,needed),days=Array.from({length:plannerDays},()=>[]);
 let dayIndex=0,lastRegion="";
 chosen.forEach(place=>{const region=placeRegion(place.id);if(days[dayIndex].length>=perDay&&dayIndex<plannerDays-1)dayIndex++;if(lastRegion&&region!==lastRegion&&days[dayIndex].length&&dayIndex<plannerDays-1)dayIndex++;days[dayIndex].push(place);lastRegion=region});
 const title=lang==="es"?"Tu ruta personalizada de "+plannerDays+" días":lang==="fr"?"Votre itinéraire personnalisé de "+plannerDays+" jours":"Your personalized "+plannerDays+"-day route";
 const selectedText=themes.map(x=>document.querySelector('.interest[value="'+x+'"] span i')?.textContent).filter(Boolean).join(" · ");
 let output='<div class="trip-summary"><div><span class="kicker">'+(lang==="es"?"TU VIAJE":lang==="fr"?"VOTRE VOYAGE":"YOUR TRIP")+'</span><h2>'+title+'</h2><p>'+selectedText+'</p></div><button class="outline" onclick="window.print()">🖨️ '+(lang==="es"?"Imprimir":lang==="fr"?"Imprimer":"Print")+'</button></div><div class="itinerary-days">';
 days.forEach((list,index)=>{if(!list.length)return;const region=placeRegion(list[0].id);output+='<article class="itinerary-day"><div class="day-head"><strong>'+(lang==="es"?"Día ":lang==="fr"?"Jour ":"Day ")+(index+1)+'</strong><span>'+regionLabel(region)+'</span></div><div class="day-stops">'+list.map((p,stop)=>'<button data-trip-place="'+p.id+'"><span class="stop-number">'+(stop+1)+'</span><span class="stop-emoji">'+p.emoji+'</span><span><b>'+(lang==="es"?p.es:p.name)+'</b><small>'+p.city+' · '+categoryLabel(p.category)+'</small></span><em>›</em></button>').join("")+'</div></article>'});
 output+='</div><div class="planner-notes"><b>💡 '+(lang==="es"?"Consejo":lang==="fr"?"Conseil":"Tip")+'</b><span>'+(lang==="es"?"Confirma horarios, clima, reservas y tiempo de traslado antes de viajar. El orden sugerido reduce cruces largos, pero no reemplaza una ruta GPS en tiempo real.":lang==="fr"?"Vérifiez les horaires, la météo, les réservations et les temps de trajet avant le départ. L’ordre suggéré limite les longs détours, mais ne remplace pas un itinéraire GPS en temps réel.":"Confirm hours, weather, reservations and travel time before departure. The suggested order reduces long crossings but does not replace live GPS routing.")+'</span></div>';
 const box=document.getElementById("tripOutput");box.innerHTML=output;box.classList.add("visible");box.querySelectorAll("[data-trip-place]").forEach(button=>button.onclick=()=>openPlace(+button.dataset.tripPlace));box.scrollIntoView({behavior:"smooth",block:"start"});
}

