function busModeLabel(mode){return mode==="public"?(lang==="es"?"Bus público":"Public bus"):(lang==="es"?"Transporte turístico":"Tourist shuttle")}
function busMapUrl(query){return "https://www.google.com/maps/search/?api=1&query="+encodeURIComponent(query+", El Salvador")}
function boardingLinks(route){
 const point=boardingPoints[route.route];if(!point)return "";
 const boardLabel=lang==="es"?"Dónde abordar":"Where to board",transferLabel=lang==="es"?"Dónde transbordar":"Where to transfer";
 let output='<div class="boarding-point"><span>'+boardLabel+'</span><a href="'+busMapUrl(point.query)+'" target="_blank" rel="noopener">📍 '+(lang==="es"?point.boardEs:point.board)+' <b>OPEN MAP ↗</b></a></div>';
 if(point.transfer)output+='<div class="boarding-point transfer-point"><span>'+transferLabel+'</span><a href="'+busMapUrl(point.transferQuery)+'" target="_blank" rel="noopener">🔄 '+(lang==="es"?point.transferEs:point.transfer)+' <b>OPEN MAP ↗</b></a></div>';
 return output;
}
function renderBus(){
 const box=document.getElementById("busResults");if(!box)return;
 const q=document.getElementById("busSearch").value.toLowerCase().trim(),mode=document.getElementById("busMode").value;
 const list=busRoutes.filter(r=>(mode==="all"||r.mode===mode)&&(!q||[r.from,r.fromEs,r.to,r.route,r.terminal,r.terminalEs].join(" ").toLowerCase().includes(q)));
 box.innerHTML=list.map(r=>'<article class="bus-route"><div class="bus-route-top"><span class="mode '+r.mode+'">'+busModeLabel(r.mode)+'</span><strong>'+r.route.replace("Shared shuttle",lang==="es"?(r.routeEs||r.route):r.route)+'</strong></div><h3><a class="place-map-link" href="'+busMapUrl(lang==="es"?r.fromEs:r.from)+'" target="_blank" rel="noopener" title="'+(lang==="es"?"Abrir origen en Google Maps":"Open origin in Google Maps")+'">'+(lang==="es"?r.fromEs:r.from)+' <em>↗</em></a> <span>→</span> <a class="place-map-link" href="'+busMapUrl(r.to)+'" target="_blank" rel="noopener" title="'+(lang==="es"?"Abrir destino en Google Maps":"Open destination in Google Maps")+'">'+r.to+' <em>↗</em></a></h3><div class="route-facts"><span>⏱️ <b>'+r.time+'</b></span><span>💵 <b>'+(lang==="es"?(r.fareEs||r.fare):r.fare)+'</b></span></div>'+boardingLinks(r)+'<p>'+(lang==="es"?r.noteEs:r.note)+'</p></article>').join("")||'<p class="bus-empty">'+(lang==="es"?"No se encontraron rutas.":"No routes found.")+'</p>';
}

