const descriptionFR={1:"Lac de cratère volcanique aux eaux bleues, avec restaurants, promenades en bateau et couchers de soleil.",2:"Montez au plus haut volcan du Salvador et admirez son lac de cratère turquoise.",3:"Village de surf emblématique réputé pour ses vagues, couchers de soleil, restaurants et vie nocturne.",4:"Escapade fraîche en montagne avec un sentier accessible donnant sur un vaste cratère.",5:"Monuments, places, marchés et Palais national dans le centre revitalisé de la capitale.",6:"Ville coloniale pavée riche en art, histoire et vues sur le lac.",7:"Campez au-dessus du golfe de Fonseca pour admirer le lever du soleil sur les îles volcaniques.",8:"Eau turquoise, forêt de pins et piscines naturelles paisibles dans l’est du Salvador.",9:"Important lieu de mémoire et de réflexion sur l’histoire de la guerre civile.",10:"Lagune volcanique émeraude près d’une charmante ville des hautes terres.",11:"Longue plage décontractée et porte d’entrée vers la côte est.",12:"Patrimoine autochtone, traditions artisanales et marché nocturne distinctif.",13:"Site de l’UNESCO préservant la vie d’un ancien village sous les cendres volcaniques.",14:"Côte de récifs pour la plongée, les fruits de mer et l’observation des baleines.",15:"Goûtez au plat national dans les pupuserías animées de Planes de Renderos.",16:"Murales, café, climat frais et ambiance de fin de semaine sur la Ruta de las Flores.",17:"Forêt de nuages, orchidées et sentiers de montagne à la rencontre de trois pays.",18:"Naviguez entre îles volcaniques, communautés de pêcheurs et paysages spectaculaires.",19:"Principale porte d’entrée internationale du pays, à environ 40 kilomètres de San Salvador.",20:"Impressionnant complexe archéologique maya avec une structure monumentale et un musée.",21:"Important centre cérémoniel et administratif préhispanique de la vallée de Zapotitán.",22:"Vaste ville préhispanique fortifiée avec pyramides, places et terrain de jeu de balle.",23:"Bar populaire de musique en direct dans la Zona Rosa. Vérifiez la programmation avant votre visite.",24:"Brasserie artisanale salvadorienne avec bière brassée sur place, repas et animations.",25:"Gastrobar élégant sur un toit avec cocktails et vues panoramiques du centre historique.",26:"Boîte de nuit pour adultes avec DJ. Confirmez les réservations, le prix d’entrée et la tenue.",27:"Quartier balnéaire accessible à pied avec bars, musique et danse la fin de semaine.",28:"Grand hôpital public national de référence. Pour une urgence médicale, composez le 132.",29:"Hôpital privé du quartier Escalón. Confirmez les soins, les coûts et la couverture.",30:"Hôpital public régional desservant l’ouest du Salvador. Composez le 132 en cas d’urgence.",31:"Hôpital public régional de référence pour l’est du Salvador. Composez le 132 en cas d’urgence.",32:"Hôpital public desservant le Morazán. Composez le 132 pour une aide urgente.",33:"Centre public de soins primaires près de la côte; ce n’est pas un hôpital d’urgence complet.",34:"Communauté où le mouvement Bitcoin du Salvador a commencé. Demandez avant de payer et gardez des dollars en réserve.",35:"Puissante vague droite de classe mondiale sur fond rocheux, pour surfeurs avancés et experts.",36:"Longue vague droite populaire auprès des intermédiaires; les débutants devraient être accompagnés.",37:"Base de surf animée avec plusieurs vagues proches, location de planches et leçons.",38:"Communauté de surf reconnue; les zones rocheuses exigent des conseils locaux.",39:"Vague droite de grande qualité sur la côte est, adaptée aux niveaux intermédiaire et avancé.",40:"Vague rocheuse éloignée et exigeante. Organisez le transport et un accompagnement local."};
const placeMapQueries={23:"Republik Bar Calle La Reforma 243 San Salvador",24:"Cadejo Brewing Company Zona Rosa Calle La Reforma 222 San Salvador",25:"Ceache Rooftop Edificio Fenix 2a Avenida Sur San Salvador",26:"Superb Club Plaza Adastra San Salvador",27:"El Tunco nightlife La Libertad",28:"Hospital Nacional Rosales San Salvador",29:"Hospital de Diagnostico Escalon San Salvador",30:"Hospital Nacional San Juan de Dios Santa Ana El Salvador",31:"Hospital Regional San Juan de Dios San Miguel El Salvador",32:"Hospital Nacional Hector Antonio Hernandez Flores San Francisco Gotera",33:"Unidad Comunitaria de Salud Familiar Puerto de La Libertad",34:"Bitcoin Beach El Zonte El Salvador",35:"Punta Roca surf break La Libertad El Salvador",36:"El Sunzal surf break El Salvador",37:"El Tunco surf break El Salvador",38:"El Zonte surf break El Salvador",39:"Playa Las Flores surf Chirilagua El Salvador",40:"Punta Mango surf Jucuaran El Salvador"};
const destinationGuideUrls={1:"/places/lake-coatepeque",2:"/places/santa-ana-volcano",3:"/places/el-tunco",5:"/places/san-salvador-historic-center",16:"/places/ruta-de-las-flores",6:"/places/suchitoto",7:"/places/conchagua-volcano",8:"/places/rio-sapo",11:"/places/el-cuco-beach",13:"/places/joya-de-ceren"};
const destinationGuideSlugs=["el-tunco","santa-ana-volcano","lake-coatepeque","ruta-de-las-flores","san-salvador-historic-center","suchitoto","conchagua-volcano","rio-sapo","el-cuco-beach","joya-de-ceren"];
const categoryLabel=value=>lang==="es"?(categoryES[value]||value):lang==="fr"?(categoryFR[value]||value):(categoryEN[value]||value);
let lang=location.pathname.startsWith("/fr")?"fr":(localStorage.estgLang||"en"),want=new Set(JSON.parse(localStorage.estgWant||"[]")),visited=new Set(JSON.parse(localStorage.estgVisited||"[]")),selected=0,special="";
const map=L.map("map",{zoomControl:true}).setView([13.73,-88.87],8);
const roadLayer=L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:'&copy; <a href="https://openstreetmap.org/copyright">OpenStreetMap</a>'});
const satelliteLayer=L.tileLayer("https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}",{maxZoom:19,attribution:"Tiles &copy; Esri, Maxar, Earthstar Geographics"});
roadLayer.addTo(map);
L.control.layers({"🛣️ Route / Road / Calles":roadLayer,"🛰️ Satellite / Satélite":satelliteLayer},null,{position:"topright",collapsed:false}).addTo(map);
const layer=L.layerGroup().addTo(map);
const t=k=>tr[lang][k]||k;
function persist(){localStorage.estgWant=JSON.stringify([...want]);localStorage.estgVisited=JSON.stringify([...visited]);counts()}
function counts(){wantCount.textContent=want.size;visitedCount.textContent=visited.size}
function fill(){let cv=category.value,dv=department.value;category.innerHTML='<option value="">'+t("allCat")+'</option>'+[...new Set(places.map(p=>p.category))].sort().map(x=>'<option value="'+x+'">'+categoryLabel(x)+'</option>').join("");department.innerHTML='<option value="">'+t("allDep")+'</option>'+[...new Set(places.map(p=>p.department))].sort().map(x=>'<option>'+x+'</option>').join("");category.value=cv;department.value=dv}
function data(){let q=search.value.toLowerCase(),c=category.value,d=department.value;return places.filter(p=>(!q||[p.name,p.es,p.city,p.department].join(" ").toLowerCase().includes(q))&&(!c||p.category===c)&&(!d||p.department===d)&&(!special||(special==="want"?want:visited).has(p.id)))}
const escapeHtml=value=>String(value).replace(/[&<>"']/g,character=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[character]));
function render(){let list=data();layer.clearLayers();count.textContent=list.length;cards.innerHTML=list.map(p=>'<button class="card" data-id="'+p.id+'"><span class="thumb" style="background:'+colors[p.category]+'22">'+(p.image?'<img src="'+p.image+'" alt="" loading="lazy">':'<span>'+p.emoji+'</span>')+'<b class="category-badge">'+p.emoji+'</b></span><span><small>'+categoryLabel(p.category)+'</small><h3>'+(lang==="es"?p.es:p.name)+'</h3><p>'+p.city+' · '+p.department+'</p></span></button>').join("")||'<p style="padding:20px;color:#667169">'+t("empty")+'</p>';list.forEach(p=>{let icon=L.divIcon({className:"",html:'<div class="pin" style="background:'+colors[p.category]+'"><span>'+p.emoji+'</span></div>',iconSize:[38,38],iconAnchor:[19,38]});const name=lang==="es"?p.es:p.name,summary=lang==="es"?p.descripcion:lang==="fr"?(descriptionFR[p.id]||p.description):p.description;const tooltip='<div class="map-preview"><small>'+escapeHtml(categoryLabel(p.category))+'</small><strong>'+escapeHtml(name)+'</strong><span>'+escapeHtml(p.city+' · '+p.department)+'</span><p>'+escapeHtml(summary)+'</p></div>';L.marker([p.lat,p.lng],{icon}).addTo(layer).bindTooltip(tooltip,{className:"destination-tooltip",direction:"top",offset:[0,-32],opacity:1}).on("click",()=>openPlace(p.id))});document.querySelectorAll(".card").forEach(x=>x.onclick=()=>openPlace(+x.dataset.id))}
function translate(){document.documentElement.lang=lang;document.querySelectorAll("[data-t]").forEach(x=>x.textContent=t(x.dataset.t));document.querySelectorAll(".language-switch button").forEach(button=>{const active=button.dataset.lang===lang;button.classList.toggle("active",active);button.setAttribute("aria-pressed",String(active))});category.setAttribute("aria-label",lang==="en"?"Filter by category":lang==="es"?"Filtrar por categoría":"Filtrer par catégorie");department.setAttribute("aria-label",lang==="en"?"Filter by department":lang==="es"?"Filtrar por departamento":"Filtrer par département");search.parentElement.setAttribute("aria-label",lang==="en"?"Search destinations":lang==="es"?"Buscar destinos":"Rechercher une destination");search.placeholder=lang==="en"?"Search a place or city…":lang==="es"?"Buscar lugar o ciudad…":"Rechercher un lieu ou une ville…";document.querySelectorAll(".seo-guide-grid a").forEach((link,index)=>{const paths=["surf-spots-el-salvador","el-salvador-bus-guide","el-salvador-itinerary-3-days","el-salvador-itinerary-5-days","el-salvador-itinerary-7-days"];link.href=(lang==="fr"?"/fr/":"/")+paths[index]});document.querySelectorAll(".destination-guide-links a").forEach((link,index)=>link.href=(lang==="fr"?"/fr/places/":"/places/")+destinationGuideSlugs[index]);fill();render();renderBus();if(selected)openPlace(selected)}
function openPlace(id){let p=places.find(x=>x.id===id);selected=id;photo.style.background="linear-gradient(135deg,"+colors[p.category]+"44,#f8f5ed)";photo.innerHTML=p.image?'<img src="'+p.image+'" alt="'+(lang==="es"?p.es:p.name)+'"><span class="photo-badge">'+p.emoji+'</span>':'<span class="photo-fallback">'+p.emoji+'</span>';tag.textContent=categoryLabel(p.category);placeName.textContent=lang==="es"?p.es:p.name;location.textContent=p.city+" · "+p.department;description.textContent=lang==="es"?p.descripcion:lang==="fr"?(descriptionFR[p.id]||p.description):p.description;wantBtn.textContent=want.has(id)?t("wanted"):t("wantBtn");visitedBtn.textContent=visited.has(id)?t("done"):t("mark");wantBtn.classList.toggle("active",want.has(id));visitedBtn.classList.toggle("active",visited.has(id));directions.href=placeMapQueries[p.id]?"https://www.google.com/maps/search/?api=1&query="+encodeURIComponent(placeMapQueries[p.id]+", El Salvador"):"https://www.google.com/maps/dir/?api=1&destination="+p.lat+","+p.lng;detailsLink.hidden=!destinationGuideUrls[id];detailsLink.href=(lang==="fr"?"/fr":"")+(destinationGuideUrls[id]||"#");detailsLink.textContent=t("fullGuide");claimLink.href="/partners?place="+id+"&name="+encodeURIComponent(lang==="es"?p.es:p.name);claimLink.textContent=t("claimListing");modal.classList.add("open");document.body.classList.add("modal-open");modal.setAttribute("aria-hidden","false");setTimeout(()=>modal.querySelector(".close").focus(),0);map.setView([p.lat,p.lng],Math.max(map.getZoom(),11))}
function close(){modal.classList.remove("open");document.body.classList.remove("modal-open");modal.setAttribute("aria-hidden","true")}
document.querySelectorAll(".language-switch button").forEach(button=>button.onclick=()=>{const next=button.dataset.lang;localStorage.estgLang=next;if(next==="fr"&&!location.pathname.startsWith("/fr")){location.href="/fr";return}if(next!=="fr"&&location.pathname.startsWith("/fr")){location.href="/";return}lang=next;translate()});search.oninput=()=>{special="";render()};category.onchange=department.onchange=()=>{special="";render()};reset.onclick=()=>{special="";search.value="";category.value="";department.value="";render();map.setView([13.73,-88.87],8)};document.querySelectorAll("[data-close]").forEach(x=>x.onclick=close);document.onkeydown=e=>{if(e.key==="Escape")close()};wantBtn.onclick=()=>{want.has(selected)?want.delete(selected):want.add(selected);persist();openPlace(selected);render()};visitedBtn.onclick=()=>{visited.has(selected)?visited.delete(selected):visited.add(selected);persist();openPlace(selected);render()};wantFilter.onclick=()=>{special="want";render();document.querySelector("#explore").scrollIntoView()};visitedFilter.onclick=()=>{special="visited";render();document.querySelector("#explore").scrollIntoView()};document.querySelectorAll(".duration").forEach(button=>button.onclick=()=>{document.querySelectorAll(".duration").forEach(x=>x.classList.remove("active"));button.classList.add("active");plannerDays=+button.dataset.days});document.querySelectorAll(".interest").forEach(input=>input.onchange=()=>{if(input.value!=="mix"&&input.checked)document.querySelector('.interest[value="mix"]').checked=false});document.getElementById("generateTrip").onclick=buildItinerary;document.getElementById("medicalFilter").onclick=()=>{special="";search.value="";department.value="";category.value="Medical";render()};document.getElementById("bitcoinFilter").onclick=()=>{special="";search.value="";department.value="";category.value="Bitcoin";render()};document.getElementById("busSearch").oninput=renderBus;document.getElementById("busMode").onchange=renderBus;total.textContent=places.length;counts();translate();loadImages();const requestedPlace=Number(new URLSearchParams(location.search).get("place"));if(requestedPlace&&places.some(p=>p.id===requestedPlace)){openPlace(requestedPlace);setTimeout(()=>document.querySelector("#explore").scrollIntoView(),100)}
